INSERT INTO demo_home_blocks VALUES
    ('청자 분청 찻잔', 20, 1, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/photoreal/staging/home_best1_A.webp'),
    ('청자 분청 찻잔', 20, 2, 'h2', '청자 분청 찻잔', NULL),
    ('청자 분청 찻잔', 20, 3, 'p', '연한 비색 유약을 입혀 구운 찻잔입니다.', NULL),
    ('청자 분청 찻잔', 20, 4, 'h2', '가까이 볼수록 선명해지는 디테일', NULL),
    ('청자 분청 찻잔', 20, 5, 'p', '만든 방식: 물레에서 빚은 뒤 천천히 말려 가마에서 두 번 구워 낸 찻잔입니다.', NULL),
    ('청자 분청 찻잔', 20, 6, 'p', '쓰임새: 손에 쥐면 가볍고, 따뜻한 차를 따르면 유약 속 빛이 은은하게 올라옵니다.', NULL),
    ('청자 분청 찻잔', 20, 7, 'p', '오래 쓰는 법: 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.', NULL),
    ('청자 분청 찻잔', 20, 8, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/photoreal/staging/home_best1_B.webp'),
    ('청자 분청 찻잔', 20, 9, 'h2', '가까이서 본 결과 마감', NULL),
    ('청자 분청 찻잔', 20, 10, 'p', '맑은 유약층과 은은한 비색이 가까이서 더 또렷하게 보입니다. 소재는 청자입니다.', NULL),
    ('청자 분청 찻잔', 20, 11, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/photoreal/staging/home_best1_C.webp'),
    ('청자 분청 찻잔', 20, 12, 'h2', '일상 속에서', NULL),
    ('청자 분청 찻잔', 20, 13, 'p', '차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다.', NULL),
    ('청자 분청 찻잔', 20, 14, 'p', '손으로 만든 찻잔이라 사진과 결·색이 조금씩 다를 수 있습니다.', NULL),
    ('옻칠 원형 쟁반', 18, 1, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/photoreal/staging/home_best2_A.webp'),
    ('옻칠 원형 쟁반', 18, 2, 'h2', '옻칠 원형 쟁반', NULL),
    ('옻칠 원형 쟁반', 18, 3, 'p', '나무를 둥글게 깎아 옻칠을 여러 번 덧발라 말린 쟁반입니다.', NULL),
    ('옻칠 원형 쟁반', 18, 4, 'h2', '가까이 볼수록 선명해지는 디테일', NULL),
    ('옻칠 원형 쟁반', 18, 5, 'p', '만든 방식: 나무 바탕에 천연 옻칠을 겹겹이 입혀 마무리한 소반입니다.', NULL),
